import { Controller, Get, Post, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const ROLE = '급여 담당자';
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;

function intOf(value: unknown, label: string): string {
  const s = String(value ?? '').trim();
  if (!/^-?\d+$/.test(s)) {
    throw new ApiError(400, 'VALIDATION_FAILED', label + '은(는) 정수여야 합니다.');
  }
  return s;
}

function optIntOf(value: unknown, label: string): string | null {
  if (value === undefined || value === null || String(value).trim() === '') {
    return null;
  }
  return intOf(value, label);
}

function pagingOf(q: Record<string, unknown>): { page: number; size: number } {
  const page = q['page'] === undefined || q['page'] === '' ? 0 : Number(intOf(q['page'], '페이지'));
  const size = q['size'] === undefined || q['size'] === '' ? DEFAULT_SIZE : Number(intOf(q['size'], '크기'));
  if (page < 0 || size < 1) {
    throw new ApiError(400, 'VALIDATION_FAILED', '페이지 값이 올바르지 않습니다.');
  }
  return { page, size: Math.min(size, MAX_SIZE) };
}

@Controller('api/v1')
export class FnSfr02308Controller {
  @Get('/year-end-data/withholding-ledgers')
  async listWithholdingLedgers(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const q = checks.queryOf(req.query);
    const year = intOf(q['settlementYear'], '귀속 연도');
    const departmentId = optIntOf(q['departmentId'], '부서');
    const employeeId = optIntOf(q['employeeId'], '임직원');
    const { page, size } = pagingOf(q);
    return transaction(async (db) => {
      const where = `FROM year_end_data d
        JOIN employee e ON e.employee_id = d.employee_id
        WHERE d.settlement_year = CAST(:year AS integer)
        AND (CAST(:departmentId AS bigint) IS NULL OR e.department_id = CAST(:departmentId AS bigint))
        AND (CAST(:employeeId AS bigint) IS NULL OR d.employee_id = CAST(:employeeId AS bigint))`;
      const items = await db.query(
        `SELECT d.employee_id AS "employeeId", e.name AS "employeeName",
          d.settlement_year AS "settlementYear", bool_and(d.closed_yn) AS "closedYn",
          CAST(COALESCE(SUM(d.deduction_amount), 0) AS numeric) AS "totalDeductionAmount"
        ${where}
        GROUP BY d.employee_id, e.name, d.settlement_year
        ORDER BY d.employee_id
        LIMIT CAST(:size AS integer) OFFSET CAST(:offset AS integer)`,
        { year, departmentId, employeeId, size, offset: page * size },
      );
      const totalRows = await db.query(
        `SELECT COUNT(DISTINCT d.employee_id) AS total ${where}`,
        { year, departmentId, employeeId },
      );
      return { items, page, size, total: Number(totalRows[0].total) };
    });
  }

  @Post('/year-end-installments')
  @HttpCode(200)
  async createYearEndInstallment(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const data = checks.inputOf(req.body);
    const employeeId = intOf(data['employeeId'], '임직원');
    const year = intOf(data['settlementYear'], '정산 연도');
    const no = intOf(data['installmentNo'], '분납 회차');
    const amount = String(data['installmentAmount'] ?? '').trim();
    if (!/^\d+(\.\d{1,2})?$/.test(amount) || Number(amount) <= 0) {
      throw new ApiError(400, 'VALIDATION_FAILED', '회차별 분납액은 0보다 큰 숫자여야 합니다.');
    }
    if (Number(no) <= 0) {
      throw new ApiError(400, 'VALIDATION_FAILED', '분납 회차는 1 이상이어야 합니다.');
    }
    return transaction(async (db) => {
      const emp = await db.query(
        'SELECT employee_id FROM employee WHERE employee_id = CAST(:employeeId AS bigint)',
        { employeeId },
      );
      if (emp.length === 0) {
        throw new ApiError(404, 'NOT_FOUND', '임직원을 찾을 수 없습니다.');
      }
      const dup = await db.query(
        `SELECT 1 FROM year_end_installment
        WHERE employee_id = CAST(:employeeId AS bigint)
        AND settlement_year = CAST(:year AS integer)
        AND installment_no = CAST(:no AS integer)`,
        { employeeId, year, no },
      );
      if (dup.length > 0) {
        throw new ApiError(400, 'VALIDATION_FAILED', '이미 입력된 분납 회차입니다.');
      }
      // 가정: 차감징수세액의 출처 테이블이 스펙에 없어, 같은 대상자·연도의 기존 분납 행에 저장된 total_levy_tax를 사용한다.
      const levyRows = await db.query(
        `SELECT MAX(total_levy_tax) AS "levy" FROM year_end_installment
        WHERE employee_id = CAST(:employeeId AS bigint)
        AND settlement_year = CAST(:year AS integer)`,
        { employeeId, year },
      );
      const levy = levyRows[0]?.levy;
      if (levy === null || levy === undefined || Number(levy) <= 0) {
        throw new ApiError(422, 'NO_LEVY_TAX_FOR_INSTALLMENT', '차감징수세액이 없는 대상자에는 분납을 입력할 수 없습니다.');
      }
      const sumRows = await db.query(
        `SELECT (COALESCE(SUM(installment_amount), 0) + CAST(:amount AS numeric)) > CAST(:levy AS numeric) AS "over"
        FROM year_end_installment
        WHERE employee_id = CAST(:employeeId AS bigint)
        AND settlement_year = CAST(:year AS integer)`,
        { employeeId, year, amount, levy: String(levy) },
      );
      if (sumRows[0].over) {
        throw new ApiError(422, 'INSTALLMENT_SUM_MISMATCH', '회차별 분납액 합계가 차감징수세액을 초과합니다.');
      }
      const rows = await db.query(
        `INSERT INTO year_end_installment
          (employee_id, settlement_year, installment_no, installment_amount, total_levy_tax, created_at, updated_at)
        VALUES (CAST(:employeeId AS bigint), CAST(:year AS integer), CAST(:no AS integer),
          CAST(:amount AS numeric), CAST(:levy AS numeric), now(), now())
        RETURNING year_end_installment_id AS "yearEndInstallmentId", total_levy_tax AS "totalLevyTax"`,
        { employeeId, year, no, amount, levy: String(levy) },
      );
      return rows[0];
    });
  }

  @Get('/year-end-installments')
  async listYearEndInstallments(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const q = checks.queryOf(req.query);
    const year = intOf(q['settlementYear'], '정산 연도');
    const employeeId = optIntOf(q['employeeId'], '임직원');
    const { page, size } = pagingOf(q);
    return transaction(async (db) => {
      const where = `FROM year_end_installment
        WHERE settlement_year = CAST(:year AS integer)
        AND (CAST(:employeeId AS bigint) IS NULL OR employee_id = CAST(:employeeId AS bigint))`;
      const items = await db.query(
        `SELECT year_end_installment_id AS "yearEndInstallmentId", employee_id AS "employeeId",
          settlement_year AS "settlementYear", installment_no AS "installmentNo",
          installment_amount AS "installmentAmount", total_levy_tax AS "totalLevyTax"
        ${where}
        ORDER BY employee_id, installment_no
        LIMIT CAST(:size AS integer) OFFSET CAST(:offset AS integer)`,
        { year, employeeId, size, offset: page * size },
      );
      const totalRows = await db.query(`SELECT COUNT(*) AS total ${where}`, { year, employeeId });
      return { items, page, size, total: Number(totalRows[0].total) };
    });
  }
}

