import { useState } from 'react';
import {
  call, useData, Num, Badge, Filters, Band, DataTable, Pager, Drawer, Form, Field,
  NumberInput, LookupSelect, RefName, Tiles, ErrorText,
} from '../kit';
import type { PageProps, Page, Row } from '../kit';

const SIZE = 20;
const EMPTY: Page = { items: [], page: 0, size: SIZE, total: 0 };

export default function FnSfr02308Page({ role, notify }: PageProps) {
  const [year, setYear] = useState<unknown>('');
  const [employee, setEmployee] = useState<unknown>('');
  const [applied, setApplied] = useState<{ year: unknown; employee: unknown }>({ year: '', employee: '' });
  const [ledgerPage, setLedgerPage] = useState(0);
  const [instPage, setInstPage] = useState(0);
  const [open, setOpen] = useState(false);
  const [form, setForm] = useState<Row>({});

  const ledgers = useData<Page>(async () => {
    if (!applied.year) return EMPTY;
    return call<Page>('GET', '/year-end-data/withholding-ledgers', role, undefined, {
      settlementYear: applied.year,
      employeeId: applied.employee,
      page: ledgerPage,
      size: SIZE,
    });
  }, [applied, ledgerPage]);

  const installments = useData<Page>(async () => {
    if (!applied.year) return EMPTY;
    return call<Page>('GET', '/year-end-installments', role, undefined, {
      settlementYear: applied.year,
      employeeId: applied.employee,
      page: instPage,
      size: SIZE,
    });
  }, [applied, instPage]);

  const ledgerData = ledgers.data ?? EMPTY;
  const instData = installments.data ?? EMPTY;
  const closedCount = ledgerData.items.filter((r) => r.closedYn === true).length;

  function search() {
    setLedgerPage(0);
    setInstPage(0);
    setApplied({ year, employee });
  }

  function reset() {
    setYear('');
    setEmployee('');
    setLedgerPage(0);
    setInstPage(0);
    setApplied({ year: '', employee: '' });
  }

  async function submit() {
    if (!form.employeeId || !form.settlementYear || !form.installmentNo || !form.installmentAmount) {
      throw new Error('임직원, 정산 연도, 분납 회차, 회차별 분납액을 모두 입력하세요.');
    }
    await call('POST', '/year-end-installments', role, {
      employeeId: form.employeeId,
      settlementYear: form.settlementYear,
      installmentNo: form.installmentNo,
      installmentAmount: form.installmentAmount,
    });
    notify('분납 내역을 저장했습니다.');
    setOpen(false);
    setForm({});
    installments.reload();
    ledgers.reload();
  }

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>연말정산 현황</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="귀속 연도" required>
            <NumberInput value={year} onChange={setYear} />
          </Field>
          <Field label="임직원">
            <LookupSelect table="employee" role={role} value={employee} onChange={setEmployee} />
          </Field>
        </Filters>
        <Tiles items={[
          ['대상자', <Num value={ledgerData.total} />],
          ['마감 대상자(현재 쪽)', <Num value={closedCount} />],
          ['분납 내역', <Num value={instData.total} />],
        ]} />
      </section>
      <section className="box span-6">
        <h2>원천징수부</h2>
        {ledgers.error ? <ErrorText text={ledgers.error} /> : null}
        <Band total={ledgerData.total} />
        <DataTable
          columns={[
            { key: 'employeeName', label: '성명' },
            { key: 'settlementYear', label: '귀속 연도' },
            { key: 'closedYn', label: '마감 여부', render: (r) => <Badge value={r.closedYn === true ? '마감' : '미마감'} /> },
            { key: 'totalDeductionAmount', label: '공제액 합계', render: (r) => <Num value={r.totalDeductionAmount} /> },
          ]}
          rows={ledgerData.items}
          empty={applied.year ? '조회 결과가 없습니다.' : '귀속 연도를 입력하고 조회하세요.'}
        />
        <Pager page={ledgerPage} size={SIZE} total={ledgerData.total} onPage={setLedgerPage} />
      </section>
      <section className="box span-6">
        <h2>분납 내역</h2>
        {installments.error ? <ErrorText text={installments.error} /> : null}
        <Band total={instData.total}>
          <button type="button" onClick={() => { setForm({ settlementYear: applied.year, employeeId: applied.employee }); setOpen(true); }}>
            분납 입력
          </button>
        </Band>
        <DataTable
          columns={[
            { key: 'employeeId', label: '임직원', render: (r) => <RefName table="employee" role={role} value={r.employeeId} /> },
            { key: 'settlementYear', label: '정산 연도' },
            { key: 'installmentNo', label: '분납 회차' },
            { key: 'installmentAmount', label: '회차별 분납액', render: (r) => <Num value={r.installmentAmount} /> },
            { key: 'totalLevyTax', label: '차감징수세액', render: (r) => <Num value={r.totalLevyTax} /> },
          ]}
          rows={instData.items}
          empty={applied.year ? '조회 결과가 없습니다.' : '귀속 연도를 입력하고 조회하세요.'}
        />
        <Pager page={instPage} size={SIZE} total={instData.total} onPage={setInstPage} />
      </section>
      {open ? (
        <Drawer title="분납 입력" onClose={() => setOpen(false)}>
          <Form onSubmit={submit} submit="저장">
            <Field label="임직원" required>
              <LookupSelect table="employee" role={role} value={form.employeeId} onChange={(v) => setForm({ ...form, employeeId: v })} />
            </Field>
            <Field label="정산 연도" required>
              <NumberInput value={form.settlementYear} onChange={(v) => setForm({ ...form, settlementYear: v })} />
            </Field>
            <Field label="분납 회차" required>
              <NumberInput value={form.installmentNo} onChange={(v) => setForm({ ...form, installmentNo: v })} />
            </Field>
            <Field label="회차별 분납액" required>
              <NumberInput value={form.installmentAmount} onChange={(v) => setForm({ ...form, installmentAmount: v })} />
            </Field>
          </Form>
        </Drawer>
      ) : null}
    </div>
  );
}
